function f(t,o){return(typeof t=="string"?new Date(t):t).toLocaleDateString("en-US",{year:"numeric",month:"short",day:"numeric",...o})}function a(t,o=1){return t>=1e6?`${(t/1e6).toFixed(o)}M`:t>=1e3?`${(t/1e3).toFixed(o)}K`:t.toFixed(0)}function c(t,o=2){if(t===0)return"0 B";const r=1024,e=o<0?0:o,i=["B","KB","MB","GB","TB"],n=Math.floor(Math.log(t)/Math.log(r));return`${parseFloat((t/Math.pow(r,n)).toFixed(e))} ${i[n]}`}function s(t,o=1){return`${(t*100).toFixed(o)}%`}export{a,f as b,s as c,c as f};
